export const getTeamHistoryUrl = (
  organizationId: string,
  teamId: string,
  params?: TeamHistoryParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/organizations/${organizationId}/teams/${teamId}/history?${stringifiedParams}`
    : `/organizations/${organizationId}/teams/${teamId}/history`;
};

/**
 * @summary Team History
 */
export const teamHistory = async (
  organizationId: string,
  teamId: string,
  params?: TeamHistoryParams,
  options?: Parameters<typeof customInstance>[1]
): Promise<TeamHistoryResponse> => {
  return customInstance<TeamHistoryResponse>(
    getTeamHistoryUrl(organizationId, teamId, params),
    {
      ...options,
      method: "GET",
    }
  );
};

export const getTeamHistoryQueryKey = (
  organizationId: string,
  teamId: string,
  params?: TeamHistoryParams
) => {
  return [
    `/organizations/${organizationId}/teams/${teamId}/history`,
    ...(params ? [params] : []),
  ] as const;
};

